#include <iostream>
using namespace std;

const int N = 100000;
int val[N], nxt[N], head, idx;

void init() { head = -1; idx = 0; }

void insertHead(int x) {
    val[idx] = x;
    nxt[idx] = head;
    head = idx++;
}

int main() {
    init();
    insertHead(3);
    insertHead(2);
    insertHead(1);
    for (int i = head; i != -1; i = nxt[i])
        cout << val[i] << " ";
    return 0;
}

#include <iostream>
using namespace std;

const int N = 100000;
int val[N], pre[N], nxt[N], idx;

void init() { nxt[0] = 1; pre[1] = 0; idx = 2; }

void insert(int k, int x) {
    val[idx] = x;
    nxt[idx] = nxt[k];
    pre[nxt[k]] = idx;
    nxt[k] = idx;
    pre[idx] = k;
    idx++;
}

int main() {
    init();
    insert(0, 10);
    for (int i = nxt[0]; i != 1; i = nxt[i])
        cout << val[i] << " ";
    return 0;
}

#include <iostream>
using namespace std;

const int N = 100010;
int val[N], nxt[N], head = -1, idx = 0;

void addHead(int x) {
    val[idx] = x; nxt[idx] = head; head = idx++;
}

void addAfter(int k, int x) {
    val[idx] = x; nxt[idx] = nxt[k]; nxt[k] = idx++;
}

void remove(int k) {
    nxt[k] = nxt[nxt[k]];
}

int main() {
    addHead(1); addHead(2); addHead(3);
    for (int i = head; ~i; i = nxt[i])
        cout << val[i] << " ";
    return 0;
}
